type Item struct {
    value    string
    priority int
    index    int   // maintained by heap.Fix / heap.Remove
}

type PriorityQueue []*Item

func (pq PriorityQueue) Len() int            { return len(pq) }
func (pq PriorityQueue) Less(i, j int) bool  { return pq[i].priority > pq[j].priority }  // min-heap
func (pq PriorityQueue) Swap(i, j int)       { pq[i], pq[j] = pq[j], pq[i]; pq[i].index = i; pq[j].index = j }
func (pq *PriorityQueue) Push(x any)         { item := x.(*Item); item.index = len(*pq); *pq = append(*pq, item) }
func (pq *PriorityQueue) Pop() any {
    old := *pq; n := len(old); item := old[n-1]   // Pop removes the LAST element, not the root
    old[n-1] = nil; *pq = old[:n-1]; return item
}

func (pq *PriorityQueue) PushPriority(item *Item) { heap.Push(pq, item) }
func (pq *PriorityQueue) PopItem() *Item          { return heap.Pop(pq).(*Item) }
